\begin{align}
        r_b = \frac{3\sqrt[3]{2}}{\sqrt{2}} = \frac{3 * 2^{1/3}}{2^{1/2}} = 3 * 2^{1/3 - 1/2} = 3 * 2^{-1/6} = \frac{3}{\sqrt[6]{2}}
    \end{align}
